<?php
namespace AdmidioPlugin\EventAttendance\Presenter;
use Admidio\Infrastructure\Plugins\Plugin;
use Admidio\Infrastructure\Utils\SecurityUtils;
use Admidio\UI\Presenter\FormPresenter;
use Admidio\UI\Presenter\PagePresenter;
final class TrackerFormPresenter { public function create(PagePresenter $page, Plugin $plugin): void { global $gCurrentOrgId, $gCurrentSession, $gDb, $gL10n; $form = new FormPresenter('adm_event_attendance_tracker_form', 'plugin.event-attendance.tracker.edit.tpl', SecurityUtils::encodeUrl($plugin->getUrl('index.php'), ['mode' => 'save'])); $form->addInput('tracker_name', $gL10n->get('SYS_NAME'), '', ['maxLength' => 100, 'property' => FormPresenter::FIELD_REQUIRED]); $form->addMultilineTextInput('tracker_description', $gL10n->get('SYS_DESCRIPTION'), '', 4, ['maxLength' => 1000]); $form->addSelectBoxFromSql('tracker_roles', $gL10n->get('SYS_GROUPS_ROLES'), $gDb, ['query' => 'SELECT rol_id, rol_name FROM ' . TBL_ROLES . ' INNER JOIN ' . TBL_CATEGORIES . ' ON cat_id = rol_cat_id WHERE rol_valid = true AND rol_system = false AND cat_org_id = ? ORDER BY cat_sequence, rol_name', 'params' => [$gCurrentOrgId]], ['multiselect' => true]); $form->addSelectBoxFromSql('tracker_events', $gL10n->get('SYS_EVENTS'), $gDb, ['query' => 'SELECT dat_id, dat_headline FROM ' . TBL_EVENTS . ' INNER JOIN ' . TBL_CATEGORIES . ' ON cat_id = dat_cat_id WHERE cat_org_id = ? ORDER BY dat_begin DESC', 'params' => [$gCurrentOrgId]], ['multiselect' => true]); $form->addSelectBoxFromSql('tracker_recurrences', $gL10n->get('SYS_RECURRENCE'), $gDb, ['query' => 'SELECT evr_id, dat_headline FROM ' . TBL_EVENT_RECURRENCES . ' INNER JOIN ' . TBL_EVENTS . ' ON dat_id = evr_dat_id_master INNER JOIN ' . TBL_CATEGORIES . ' ON cat_id = dat_cat_id WHERE cat_org_id = ? ORDER BY dat_begin DESC', 'params' => [$gCurrentOrgId]], ['multiselect' => true]); $form->addSubmitButton('adm_button_save_tracker', $gL10n->get('SYS_SAVE'), ['icon' => 'bi-check-lg', 'class' => 'offset-sm-3']); $form->addToSmarty($page->getSmartyTemplate()); $gCurrentSession->addFormObject($form); $page->addTemplateFile('plugin.event-attendance.tracker.edit.tpl'); } }
